mapper.select:
select s.id, s.season_id as seasonId, se.season_name as seasonName, s.stage_id as stageId, st.stage_name as stageName, s.team_id as teamId, t.team_no as teamNo, t.team_name as teamName, t.short_name as shortName, lf.access_url as logoUrl, s.games, s.wins, s.losses, s.points_for as pointsFor, s.points_against as pointsAgainst, s.avg_points as avgPoints, s.avg_points_against as avgPointsAgainst, s.avg_rebounds as avgRebounds, s.avg_assists as avgAssists, s.avg_steals as avgSteals, s.avg_blocks as avgBlocks, s.avg_turnovers as avgTurnovers, s.field_goal_pct as fieldGoalPct, s.three_point_pct as threePointPct, s.free_throw_pct as freeThrowPct, s.win_rate as winRate, s.last_calculated_time as lastCalculatedTime from basket_team_season_stat s left join basket_tournament_season se on se.id = s.season_id and se.is_delete = 0 left join basket_tournament_stage st on st.id = s.stage_id and st.is_delete = 0 left join basket_team t on t.id = s.team_id and t.is_delete = 0 left join basket_file_asset lf on lf.id = t.logo_file_id and lf.is_delete = 0 where s.is_delete = 0 and s.season_id = #{seasonId} and s.stage_id = #{stageId} and s.team_id = #{teamId}
and (t.team_name like concat('%', #{keyword}, '%') or t.short_name like concat('%', #{keyword}, '%') or t.team_no like concat('%', #{keyword}, '%'))
order by s.win_rate desc, s.avg_points desc, s.team_id

mapper.delete:
delete from basket_team_season_stat
where season_id = #{seasonId}
and stage_id = #{stageId}
